import { z } from 'zod';

export const ToggleLessonInput = z.object({
  userId: z.string().uuid(),
  lessonId: z.string().min(2),
});

export async function toggleLessonProgress(db: D1Database, rawInput: unknown) {
  const parsed = ToggleLessonInput.safeParse(rawInput);
  if (!parsed.success) return { success: false, error: parsed.error.issues[0].message };

  const { userId, lessonId } = parsed.data;
  const existing = await db.prepare('SELECT id, completed FROM lesson_progress WHERE user_id = ? AND lesson_id = ?')
    .bind(userId, lessonId).first<{ id: string; completed: number }>();

  const now = new Date().toISOString();
  if (existing) {
    await db.prepare('UPDATE lesson_progress SET completed = ?, updated_at = ? WHERE id = ?')
      .bind(existing.completed ? 0 : 1, now, existing.id).run();
  } else {
    await db.prepare('INSERT INTO lesson_progress (id, user_id, lesson_id, completed, created_at, updated_at) VALUES (?, ?, ?, 1, ?, ?)')
      .bind(crypto.randomUUID(), userId, lessonId, now, now).run();
  }
  return { success: true, data: { lessonId, updated: true } };
}
