import { z } from 'zod';

export const GetProgressSchema = z.object({ userId: z.string().uuid(), moduleId: z.string() });

export const agentTools = [{
  name: 'get_progress',
  description: 'Récupère la progression réelle d’un apprenant.',
  parameters: {
    type: 'OBJECT',
    properties: {
      userId: { type: 'STRING' },
      moduleId: { type: 'STRING' }
    },
    required: ['userId', 'moduleId']
  }
}];

export async function handleToolCall(name: string, args: unknown, db: D1Database) {
  if (name === 'get_progress') {
    const parsed = GetProgressSchema.safeParse(args);
    if (!parsed.success) return { success: false, error: 'Args invalides' };
    const rows = await db.prepare('SELECT lesson_id, completed FROM lesson_progress WHERE user_id = ?').bind(parsed.data.userId).all();
    return { success: true, data: rows.results };
  }
  return { success: false, error: 'Outil inconnu' };
}
