  ({ className, children, ...props }, ref) => (
    <button
      ref={ref}
      className={cn('min-h-[44px] px-4 py-2 bg-accent text-accent-foreground font-bold rounded-xl focus-visible:ring-2', className)}
      {...props}
    >
      {children}
    </button>
  )
);
Button.displayName = 'Button';
