export async function hashPassword(password: string, salt: string): Promise<string> {
  const encoder = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey('raw', encoder.encode(password), { name: 'PBKDF2' }, false, ['deriveBits', 'deriveKey']);
  const key = await crypto.subtle.deriveKey({ name: 'PBKDF2', salt: encoder.encode(salt), iterations: 100000, hash: 'SHA-256' }, keyMaterial, { name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt']);
  const exported = await crypto.subtle.exportKey('raw', key);
  return Array.from(new Uint8Array(exported)).map(b => b.toString(16).padStart(2, '0')).join('');
}

export async function requireUserSession(db: D1Database, token?: string) {
  if (!token) throw new Error('UNAUTHORIZED');
  const session = await db.prepare('SELECT user_id, role, expires_at FROM sessions WHERE token = ?').bind(token).first<{ user_id: string; role: string; expires_at: string }>();
  if (!session || new Date(session.expires_at) < new Date()) throw new Error('UNAUTHORIZED');
  return { userId: session.user_id, role: session.role };
}
